// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;

    function setUp() public { c = new EBU(); }

    // fuzzed params: the `from` actor and a single recipient address and a single value
    // we restrict lengths to 1 so exactly one external call is made and observed
    function testFuzz_property(address from, address tosAddr, uint256 v) public {
        // keep addresses non-zero to be in normal domain
        vm.assume(from != address(0));
        vm.assume(tosAddr != address(0));

        // deploy a callee that ALWAYS reverts when transferFrom is called
        RevertingCallee rev = new RevertingCallee();

        // Prepare arrays with single entry so loop iterates exactly once
        address[] memory tos = new address[](1);
        tos[0] = tosAddr;
        uint256[] memory vals = new uint256[](1);
        vals[0] = v;

        // Call c.transfer and observe whether it reverts or not via try/catch
        bool ok;
        try c.transfer(from, address(rev), tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE: If the external callee (transferFrom) REVERTS, the reference C MUST propagate that and thus transfer MUST revert (ok == false).
        // The mutant inverts the success check and will NOT revert when the callee reverts (ok == true for some inputs).
        // We assert that the call DID revert (ok == false) — this holds for the correct C for ALL inputs where the callee reverts,
        // and the mutant will break this for some inputs (the fuzzer will find such a case).
        assertTrue(!ok);
    }
}

// adversarial helper that matches the selector transferFrom(address,address,uint256)
contract RevertingCallee {
    // match the called signature so abi.decode would succeed if called with that selector
    function transferFrom(address, address, uint256) external pure {
        revert("revert-from-callee");
    }
}
